const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Isabela Island geometry (Galapagos)
  const isabelaIsland = ee.Geometry.Polygon([
    [-91.15, -0.35], [-91.45, -0.35], [-91.45, -1.0], [-91.15, -1.0], [-91.15, -0.35]
  ]);

  // Split into northern and southern parts
  const northernPart = ee.Geometry.Polygon([
    [-91.15, -0.35], [-91.45, -0.35], [-91.45, -0.675], [-91.15, -0.675], [-91.15, -0.35]
  ]);

  const southernPart = ee.Geometry.Polygon([
    [-91.15, -0.675], [-91.45, -0.675], [-91.45, -1.0], [-91.15, -1.0], [-91.15, -0.675]
  ]);

  // Get VIIRS DNB nighttime lights data
  const startDate = '2022-01-07';
  const endDate = '2022-01-08';

  const viirsCollection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterDate(startDate, endDate)
    .filterBounds(isabelaIsland);

  // Check if collection is empty
  const collectionSize = viirsCollection.size().getInfo();
  console.log(`VIIRS Images Found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get the image and extract radiance band
  const image = viirsCollection.first();

  // Calculate average radiance for northern and southern parts
  const northStats = image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: northernPart,
    scale: 1000,
    maxPixels: 1e9
  });

  const southStats = image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: southernPart,
    scale: 1000,
    maxPixels: 1e9
  });

  // Get pixel counts to check for valid data
  const northCount = image.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: northernPart,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const southCount = image.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: southernPart,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  console.log(`North Pixels: ${northCount}, South Pixels: ${southCount}`);

  // Check for no valid pixels
  if (northCount === 0 || southCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Get radiance values
  const northRadiance = northStats.get('avg_rad').getInfo();
  const southRadiance = southStats.get('avg_rad').getInfo();

  console.log(`North Radiance: ${northRadiance ? northRadiance.toFixed(4) : 'null'}`);
  console.log(`South Radiance: ${southRadiance ? southRadiance.toFixed(4) : 'null'}`);

  // Check for calculation failures
  if (northRadiance === null || southRadiance === null || 
      isNaN(northRadiance) || isNaN(southRadiance) ||
      northRadiance < 0 || southRadiance < 0) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare radiance values
  if (northRadiance > southRadiance) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
